export declare function shortSha(sha: string): string;
export declare function resultWord(result: "pass" | "fail" | "pending"): string;
export declare function verdictWord(verdict: "approve" | "request_changes"): string;
/** `<from> <TYPE> <HH:MM:SS>` (1.7); falls back to the id when the message is unknown. */
